/* ============================================================
   أطياب الجاسم (React) — محرّك البحث (شجرة لواحق + تطبيع عربي)

   منقول حرفياً من src/search.js القديم مع تغيير واحد: الدالة mark
   ترجع مقاطع (segments) بدل HTML، ليرسمها React بأمان بلا
   dangerouslySetInnerHTML.

   · كل كلمة في بيانات المنتج تُدرَج في شجرة لواحق (Suffix Trie)،
     فيطابق البحث أي جزء من الكلمة لا بدايتها فقط («ليل» ← «عود الليل»).
   · «أ ب» = المنتجات التي تحوي الكلمتين معاً (تقاطع مجموعات).
   · الترتيب: من يبدأ اسمه بالحروف أولاً، ثم من ورد في اسمه، ثم بقية الحقول.
   ============================================================ */

import { ATYAB_SEARCH_TYPES } from "../data/appConfig.js";
import { ATYAB_allProducts, ATYAB_catalogOf } from "../data/products.js";
import { genderLabelOf } from "../i18n.js";

const DIACRITICS = /[\u064B-\u0652\u0670\u0640\u06D6-\u06ED\u08F0-\u08F2]/;
const DIGITS = /[\u0660-\u0669\u06F0-\u06F9]/;

/* تحويل حرف واحد ← حرف واحد (بلا حذف) */
export function foldChar(ch) {
  switch (ch) {
    case "\u0622":
    case "\u0623":
    case "\u0625":
    case "\u0627":
    case "\u0671":
      return "\u0627"; /* آ أ إ ا ٱ ← ا */
    case "\u0649":
      return "\u064A"; /* ى ← ي */
    case "\u0629":
      return "\u0647"; /* ة ← ه */
    case "\u0624":
      return "\u0648"; /* ؤ ← و */
    case "\u0626":
      return "\u064A"; /* ئ ← ي */
    default:
      return ch.toLowerCase();
  }
}

/* تطبيع كامل: يحذف التشكيل والترقيم ويوحّد الأرقام */
export function fold(text) {
  const raw = String(text == null ? "" : text);
  let out = "";
  for (let i = 0; i < raw.length; i++) {
    const ch = raw.charAt(i);
    if (DIACRITICS.test(ch)) continue;
    if (DIGITS.test(ch)) {
      out += String(ch.charCodeAt(0) & 0xf);
      continue;
    }
    if (/\s/.test(ch)) {
      out += " ";
      continue;
    }
    if (/[\u0621-\u064Aa-zA-Z0-9]/.test(ch)) {
      out += foldChar(ch);
      continue;
    }
    out += " ";
  }
  return out.replace(/\s+/g, " ").trim();
}

export function words(text) {
  const f = fold(text);
  return f ? f.split(" ") : [];
}

/* ---------- شجرة اللواحق ---------- */
function newNode() {
  return { kids: Object.create(null), ids: null };
}

function insertWord(root, word, id) {
  for (let start = 0; start < word.length; start++) {
    let node = root;
    for (let i = start; i < word.length; i++) {
      const ch = word.charAt(i);
      let next = node.kids[ch];
      if (!next) {
        next = newNode();
        node.kids[ch] = next;
      }
      node = next;
      if (!node.ids) node.ids = Object.create(null);
      node.ids[id] = 1;
    }
  }
}

function lookup(root, token) {
  let node = root;
  for (let i = 0; i < token.length; i++) {
    node = node.kids[token.charAt(i)];
    if (!node) return null;
  }
  return node.ids;
}

/* ---------- الفهرس ----------
   ★ يُفهرس المنتج بلغتيه: حقول nameEn/descEn/notesEn/storyEn من سجلّ
     المنتج (عمود اللغة في قاعدة البيانات) تُفهرس مع العربية، فيعمل
     البحث باللغتين معاً وبنفس الترتيب، ويُظلَّل النصّ المعروض بلغة الواجهة. */
function typeLabelOf(p, lang) {
  const types = ATYAB_SEARCH_TYPES || [];
  for (let i = 0; i < types.length; i++) {
    if (types[i].key === p.searchType) return (lang === "en" && types[i].labelEn) || types[i].label;
  }
  return lang === "en" ? "Perfume" : "عطر";
}

function recordFor(p, cat) {
  const notes = p.notes || {};
  const notesEn = p.notesEn || {};
  const typeLabel = typeLabelOf(p, "ar");
  const typeLabelEn = typeLabelOf(p, "en");
  const metaLabel = p.kindLabel || genderLabelOf(p.gender, "ar") || "";
  const metaLabelEn = p.kindLabelEn || genderLabelOf(p.gender, "en") || metaLabel;
  const rest = [p.desc, p.kindLabel, genderLabelOf(p.gender, "ar"), typeLabel, p.size, notes.top, notes.heart, notes.base, p.story]
    .filter(Boolean)
    .join(" ");
  const restEn = [p.descEn, p.kindLabelEn, genderLabelOf(p.gender, "en"), typeLabelEn, p.sizeEn, notesEn.top, notesEn.heart, notesEn.base, p.storyEn]
    .filter(Boolean)
    .join(" ");
  return {
    product: p,
    catalog: cat,
    type: p.searchType || "perfume",
    typeLabel: typeLabel,
    typeLabelEn: typeLabelEn,
    metaLabel: metaLabel,
    metaLabelEn: metaLabelEn,
    nameFold: fold(p.name),
    nameFoldEn: fold(p.nameEn || ""),
    nameWords: words(p.name),
    nameWordsEn: words(p.nameEn || ""),
    restFold: fold(rest),
    restFoldEn: fold(restEn)
  };
}

let index = null;

export function buildIndex() {
  const root = newNode();
  const records = [];
  ATYAB_allProducts().forEach(function (p) {
    const rec = recordFor(p, ATYAB_catalogOf(p.id));
    const id = records.length;
    records.push(rec);
    const seen = Object.create(null);
    rec.nameWords
      .concat(words(rec.restFold))
      .concat(rec.nameWordsEn)
      .concat(words(rec.restFoldEn))
      .forEach(function (w) {
        if (!w || seen[w]) return;
        seen[w] = 1;
        insertWord(root, w, id);
      });
  });
  index = { root: root, records: records };
  return index;
}

function indexSig() {
  try {
    const list = ATYAB_allProducts();
    let h = list.length + ":";
    for (let i = 0; i < list.length; i++) {
      const p = list[i];
      h += p.id + "," + (p.price || 0) + "," + String(p.name || "").length + ";";
      if (h.length > 4000) break;
    }
    return h.length + ":" + h.slice(0, 200);
  } catch (e) { return String(ATYAB_allProducts().length); }
}

let indexSigCache = "";

export function ensureIndex() {
  const sig = indexSig();
  if (!index || sig !== indexSigCache) { buildIndex(); indexSigCache = sig; }
  return index;
}

/* ---------- البحث ---------- */
/* فلتر فارغ أو "all" = بلا فلترة (حماية من أي حالة قديمة تمرّر "all") */
function activeType(filters) {
  const type = filters && filters.type;
  return type && type !== "all" ? type : "";
}

function activeGender(filters) {
  const gender = filters && filters.gender;
  return gender && gender !== "all" ? gender : "";
}

function matchesFilters(rec, filters) {
  const type = activeType(filters);
  const gender = activeGender(filters);
  if (type && rec.type !== type) return false;
  if (gender) {
    /* البخور بلا جنس مناسَب → لا يظهر عند اختيار جنس */
    if (rec.product.kindLabel) return false;
    return rec.product.gender === gender || rec.product.gender === "unisex";
  }
  return true;
}

/* هل الفلاتر تُضيّق النتائج فعلاً؟ (يُستعمل لتمييز «بعد الفلاتر» ودعوة البدء) */
function filtersActive(filters) {
  return !!activeType(filters) || !!activeGender(filters);
}

function hasWordStart(list, token) {
  for (let i = 0; i < list.length; i++) {
    if (list[i].indexOf(token) === 0) return true;
  }
  return false;
}

/* تقييم تطابق الاستعلام: الأعلى بين تطابق الاسم بالعربية والاسم بالإنجليزية */
function nameScore(foldName, nameWords, tokens, phrase) {
  let score = 0;
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (foldName === token) score += 260;
    else if (hasWordStart(nameWords, token)) score += 130;
    else if (foldName.indexOf(token) !== -1) score += 48;
    else score += 8;
  }
  if (phrase) {
    if (foldName === phrase) score += 420;
    else if (foldName.indexOf(phrase) !== -1) score += 170;
  }
  return score;
}

function scoreOf(rec, tokens, phrase) {
  let score = Math.max(
    nameScore(rec.nameFold, rec.nameWords, tokens, phrase),
    nameScore(rec.nameFoldEn, rec.nameWordsEn, tokens, phrase)
  );
  if (phrase) {
    const inName = rec.nameFold.indexOf(phrase) !== -1 || rec.nameFoldEn.indexOf(phrase) !== -1;
    const inRest = rec.restFold.indexOf(phrase) !== -1 || rec.restFoldEn.indexOf(phrase) !== -1;
    if (!inName && inRest) score += 34;
  }
  score += Math.min(rec.product.sales || 0, 1500) / 150;
  score += (rec.product.rating || 0) / 10;
  return score;
}

function browserSort(a, b) {
  return (b.product.sales || 0) - (a.product.sales || 0) || (b.product.rating || 0) - (a.product.rating || 0);
}

export function runSearch(query, filters, ignoreFilters) {
  const idx = ensureIndex();
  filters = filters || { type: "", gender: "" };
  const tokens = words(query);
  const phrase = tokens.join(" ");
  const pool = idx.records.filter(function (rec) {
    return ignoreFilters ? true : matchesFilters(rec, filters);
  });

  if (!tokens.length) {
    return {
      tokens: [],
      records: pool.slice().sort(browserSort),
      query: "",
      filtered: filtersActive(filters)
    };
  }

  const sets = [];
  for (let i = 0; i < tokens.length; i++) {
    const set = lookup(idx.root, tokens[i]);
    if (!set) return { tokens: tokens, records: [], query: query, filtered: filtersActive(filters) };
    sets.push(set);
  }
  sets.sort(function (a, b) {
    return Object.keys(a).length - Object.keys(b).length;
  });

  const hits = [];
  const first = sets[0];
  Object.keys(first).forEach(function (key) {
    let ok = true;
    for (let s = 1; s < sets.length; s++) {
      if (!sets[s][key]) {
        ok = false;
        break;
      }
    }
    if (ok) hits.push(idx.records[Number(key)]);
  });

  const list = hits.filter(function (rec) {
    return ignoreFilters ? true : matchesFilters(rec, filters);
  });
  const scored = list.map(function (rec) { return { r: rec, s: scoreOf(rec, tokens, phrase) }; });
  scored.sort(function (a, b) { return b.s - a.s || browserSort(a.r, b.r); });
  /* ★ R05: القائمة المرتبة في متغير مستقل (كانت const list ثم إسناد —
     استثناء no-const-assign ظهر تحذيراً وكسر البحث الفعلي). */
  const ranked = scored.map(function (x) { return x.r; });

  return { tokens: tokens, records: ranked, query: query, filtered: filtersActive(filters) };
}

/* اقتراحات عند صفر نتائج: كل كلمة على حدة مع عدد ما تطابقه */
export function suggestionsFor(query, filters) {
  const idx = ensureIndex();
  const out = [];
  words(query).forEach(function (token) {
    const set = lookup(idx.root, token);
    if (!set) return;
    let n = 0;
    Object.keys(set).forEach(function (key) {
      if (matchesFilters(idx.records[Number(key)], filters || { type: "", gender: "" })) n++;
    });
    if (n) out.push({ token: token, count: n });
  });
  return out;
}

/* ---------- تظليل أحرف البحث (مقاطع جاهزة لـReact) ---------- */
export function markSegments(text, tokens) {
  const raw = String(text == null ? "" : text);
  if (!raw || !tokens || !tokens.length) return [{ text: raw, hit: false }];

  let flat = "";
  const map = [];
  for (let i = 0; i < raw.length; i++) {
    const ch = raw.charAt(i);
    if (DIACRITICS.test(ch)) continue;
    if (DIGITS.test(ch)) { flat += String(ch.charCodeAt(0) & 0xf); map.push(i); continue; }
    const f = /\s/.test(ch) ? " " : foldChar(ch);
    for (let k = 0; k < f.length; k++) {
      flat += f[k];
      map.push(i);
    }
  }

  const ranges = [];
  tokens.forEach(function (token) {
    if (!token) return;
    let from = 0;
    let at;
    while ((at = flat.indexOf(token, from)) !== -1) {
      ranges.push([at, at + token.length]);
      from = at + token.length;
    }
  });
  if (!ranges.length) return [{ text: raw, hit: false }];

  ranges.sort(function (a, b) {
    return a[0] - b[0];
  });
  const merged = [];
  ranges.forEach(function (r) {
    const last = merged[merged.length - 1];
    if (last && r[0] <= last[1]) last[1] = Math.max(last[1], r[1]);
    else merged.push([r[0], r[1]]);
  });

  const out = [];
  let cursor = 0;
  merged.slice(0, 24).forEach(function (r) {
    const start = map[r[0]];
    const end = r[1] >= map.length ? raw.length : map[r[1]];
    if (start > cursor) out.push({ text: raw.slice(cursor, start), hit: false });
    out.push({ text: raw.slice(start, end), hit: true });
    cursor = end;
  });
  if (cursor < raw.length) out.push({ text: raw.slice(cursor), hit: false });
  return out;
}
