/* ============================================================
   أطياب الجاسم (React) — البحث (Search)

   يبحث في كل منتجات المتجر (عطور + بخور) عبر شجرة اللواحق في
   searchEngine.js، ويقرأ/يكتب حالة البحث في Redux (catalogSlice)
   — فتظل النتائج محفوظة عند التنقّل إلى منتج والعودة.

   الفلاتر: النوع (الكل · عطر · عود · بخور) و«مناسب لـ» (الكل · للذكر · للأنثى).
   النتائج بطاقات ProductCard نفسها مع تظليل أحرف البحث.
   ============================================================ */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { ATYAB_SEARCH_TYPES, ATYAB_SEARCH_GENDERS } from "../../data/appConfig.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { catalogActions } from "../../redux/slices/catalogSlice.js";
import { runSearch, suggestionsFor, markSegments } from "../../redux/searchEngine.js";
import { countLabel, productName, productDesc, tr2 } from "../../i18n.js";
import { Icon } from "../Source/Icons.jsx";
import ProductCard from "./ProductCard.jsx";

/* كلمات البحث الشائعة بلغتين — الكلمة المختارة تُكتب في الحقل، والمحرّك
   يفهرس العربية والإنجليزية معاً فيعمل البحث بالكلمتين. */
const POPULAR = [
  { ar: "عود", en: "oud" },
  { ar: "مسك", en: "musk" },
  { ar: "ورد", en: "rose" },
  { ar: "زعفران", en: "saffron" },
  { ar: "عنبر", en: "amber" },
  { ar: "بخور", en: "bakhoor" },
  { ar: "ياسمين", en: "jasmine" },
  { ar: "فانيليا", en: "vanilla" }
];

/* بنية شرائح الفلاتر بلغة الواجهة */
function chipItems(list, lang) {
  return (list || []).map(function (it) {
    return { key: it.key, label: lang === "en" ? it.labelEn || it.label : it.label };
  });
}

function Chips(props) {
  return (
    <div className="sc-chips" role="group" aria-label={props.label}>
      {props.items.map(function (item) {
        const on = props.value === item.key;
        return (
          <button
            key={item.key || "all"}
            className="sc-chip"
            type="button"
            aria-pressed={on ? "true" : "false"}
            onClick={function () {
              props.onPick(item.key);
            }}
          >
            {item.label}
          </button>
        );
      })}
    </div>
  );
}

export default function Search() {
  const dispatch = useAppDispatch();
  const filters = useAppSelector(function (s) {
    return s.catalog.search;
  });
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  /* الحقل يبدأ من حالة Redux المحفوظة (فتعود لنتائجك بعد مشاهدة عطر) */
  const [text, setText] = useState(filters.query || "");
  const [debounced, setDebounced] = useState(filters.query || "");
  const inputRef = useRef(null);

  useEffect(
    function () {
      if (inputRef.current) inputRef.current.focus({ preventScroll: true });
    },
    []
  );

  /* تأخير بسيط (70ms) كما في النسخة القديمة — يمنع رجفة النتائج */
  useEffect(
    function () {
      const id = window.setTimeout(function () {
        setDebounced(text);
      }, 70);
      return function () {
        window.clearTimeout(id);
      };
    },
    [text]
  );

  useEffect(
    function () {
      if (debounced !== filters.query) dispatch(catalogActions.setSearchQuery(debounced));
    },
    [debounced, filters.query, dispatch]
  );

  const result = useMemo(
    function () {
      return runSearch(debounced, { type: filters.type, gender: filters.gender });
    },
    [debounced, filters.type, filters.gender]
  );

  const tokens = result.tokens;
  const hasQuery = tokens.length > 0;
  const startScreen = !hasQuery && !result.filtered;
  const noHits = hasQuery && result.records.length === 0;

  const suggestions = useMemo(
    function () {
      return noHits ? suggestionsFor(debounced, { type: filters.type, gender: filters.gender }) : [];
    },
    [noHits, debounced, filters.type, filters.gender]
  );

  const blockedByFilters = useMemo(
    function () {
      if (!noHits || !result.filtered) return false;
      return runSearch(debounced, { type: filters.type, gender: filters.gender }, true).records.length > 0;
    },
    [noHits, result.filtered, debounced, filters.type, filters.gender]
  );

  const filtersLabel = useMemo(
    function () {
      const bits = [];
      ATYAB_SEARCH_TYPES.forEach(function (tp) {
        if (tp.key === filters.type) bits.push(language === "en" ? tp.labelEn || tp.label : tp.label);
      });
      ATYAB_SEARCH_GENDERS.forEach(function (g) {
        if (g.key === filters.gender) bits.push(language === "en" ? g.labelEn || g.label : g.label);
      });
      return bits.join(" · ");
    },
    [filters.type, filters.gender, language]
  );

  const setQuery = useCallback(
    function (value) {
      setText(value);
      dispatch(catalogActions.setSearchQuery(value));
      if (inputRef.current) inputRef.current.focus();
    },
    [dispatch]
  );

  const resetAll = useCallback(
    function () {
      dispatch(catalogActions.resetSearch());
      setText("");
      setDebounced("");
      if (inputRef.current) inputRef.current.focus();
    },
    [dispatch]
  );

  const clearFilters = useCallback(
    function () {
      dispatch(catalogActions.setSearch({ type: "", gender: "" }));
    },
    [dispatch]
  );

  return (
    <>
      <div className="sc-head">
        <span className="eyebrow">ابحث في المتجر</span>
        <h1>ابحث عن عطر أو عود</h1>
        <p>
          اكتب أي جزء من الاسم — حرفاً أو كلمة — وسنجمع لك كل ما يطابقه فوراً من العطور والبخور، مع فلتر للنوع وفلتر
          لمن يناسبه. اضغط على أي نتيجة لتنتقل إلى صفحة العرض.
        </p>
      </div>

      <div className="sc-panel">
        <form
          className="sc-field"
          role="search"
          noValidate
          onSubmit={function (e) {
            e.preventDefault();
            dispatch(catalogActions.setSearchQuery(text));
          }}
        >
          <Icon name="search" className="sc-field-ico" strokeWidth={1.8} />
          <label className="sr-only" htmlFor="searchInput">
            ابحث عن عطر أو عود
          </label>
          <input
            ref={inputRef}
            type="search"
            id="searchInput"
            placeholder="اكتب اسم العطر… مثال: عود"
            autoComplete="off"
            autoCapitalize="off"
            enterKeyHint="search"
            spellCheck="false"
            value={text}
            onChange={function (e) {
              setText(e.target.value);
            }}
            onKeyDown={function (e) {
              if (e.key === "Escape" && text) {
                e.stopPropagation();
                setQuery("");
              }
            }}
          />
          <button
            className="sc-clear"
            type="button"
            aria-label="مسح البحث"
            title="مسح البحث"
            hidden={!text}
            onClick={function () {
              setQuery("");
            }}
          >
            <Icon name="x" strokeWidth={2.2} />
          </button>
        </form>

        <div className="sc-filters">
          <div className="sc-filter">
            <span className="sc-filter-label">النوع</span>
            <Chips
              label="فلتر النوع"
              items={[{ key: "", label: tr2(language, "All", "الكل") }].concat(chipItems(ATYAB_SEARCH_TYPES, language))}
              value={filters.type}
              onPick={function (key) {
                dispatch(catalogActions.setSearch({ type: key }));
              }}
            />
          </div>
          <div className="sc-filter">
            <span className="sc-filter-label">مناسب لـ</span>
            <Chips
              label="فلتر الجنس"
              items={[{ key: "", label: tr2(language, "All", "الكل") }].concat(chipItems(ATYAB_SEARCH_GENDERS, language))}
              value={filters.gender}
              onPick={function (key) {
                dispatch(catalogActions.setSearch({ gender: key }));
              }}
            />
          </div>
          {text || filters.type || filters.gender ? (
            <button className="sc-reset" type="button" onClick={resetAll}>
              مسح البحث والفلاتر
            </button>
          ) : null}
        </div>
      </div>

      {startScreen ? (
        <div className="sc-hint">
          <p className="sc-suggest-title">عمليات بحث شائعة — اكتب حرفاً واحداً وسنعرض كل ما يطابقه:</p>
          <div className="sc-chips sc-suggest-chips">
            {POPULAR.map(function (word) {
              const label = language === "en" ? word.en : word.ar;
              return (
                <button
                  key={word.ar}
                  className="sc-chip sc-chip-quiet"
                  type="button"
                  onClick={function () {
                    setQuery(label);
                  }}
                >
                  {label}
                </button>
              );
            })}
          </div>
        </div>
      ) : null}

      <p className="sc-status" role="status" aria-live="polite">
        {hasQuery ? (
          <>
            {countLabel(result.records.length, language)} {tr2(language, "for", "لـ")} «<b>{debounced.trim()}</b>»
            {filtersLabel ? " — " + filtersLabel : ""}
          </>
        ) : result.filtered ? (
          <>
            {countLabel(result.records.length, language)}
            {tr2(language, " after filters", " بعد الفلاتر")}
            {filtersLabel ? " — " + filtersLabel : ""}
          </>
        ) : (
          tr2(language, "Most in demand right now:", "الأكثر طلباً الآن:")
        )}
      </p>

      <div className="grid sc-grid">
        {result.records.map(function (rec) {
          const p = rec.product;
          return (
            <ProductCard
              key={p.id}
              product={p}
              extras={{
                tag: <span className="sc-tag">{language === "en" ? rec.typeLabelEn || rec.typeLabel : rec.typeLabel}</span>,
                meta: (language === "en" ? rec.metaLabelEn || rec.metaLabel : rec.metaLabel) ? (
                  <>
                    <span className="sc-meta-dot" aria-hidden="true" />
                    {language === "en" ? rec.metaLabelEn || rec.metaLabel : rec.metaLabel}
                  </>
                ) : null,
                nameSegments: markSegments(productName(p, language), tokens),
                descSegments: markSegments(productDesc(p, language), tokens)
              }}
            />
          );
        })}
      </div>

      {noHits ? (
        <div className="grid-empty sc-empty">
          <div className="sc-empty-inner">
            {blockedByFilters ? (
              <>
                <h3>لا نتائج لكلمة «{debounced.trim()}» مع هذه الفلاتر</h3>
                <p>
                  كلمة «{debounced.trim()}» لها نتائج فعلاً، لكن الفلاتر المختارة ({filtersLabel}) تستثنيها كلها. أزل
                  الفلاتر لتظهر.
                </p>
                <button className="sc-chip sc-chip-gold" type="button" onClick={clearFilters}>
                  إزالة الفلاتر
                </button>
                <button className="sc-chip sc-chip-quiet" type="button" onClick={resetAll}>
                  إظهار كل المنتجات
                </button>
              </>
            ) : (
              <>
                <h3>لا يوجد ما يطابق «{debounced.trim()}»</h3>
                <p>تأكّد من كتابة الجزء الصحيح من الاسم، أو جرّب كلمة واحدة من الآتي:</p>
                {suggestions.length ? (
                  <>
                    <p className="sc-suggest-title">كلمات موجودة في بيانات المنتجات:</p>
                    <div className="sc-chips sc-suggest-chips">
                      {suggestions.map(function (s) {
                        return (
                          <button
                            key={s.token}
                            className="sc-chip sc-chip-quiet"
                            type="button"
                            onClick={function () {
                              setQuery(s.token);
                            }}
                          >
                            {s.token} <b>{s.count}</b>
                          </button>
                        );
                      })}
                    </div>
                  </>
                ) : null}
                <button className="sc-chip sc-chip-gold" type="button" onClick={resetAll}>
                  إزالة الفلاتر وإظهار كل المنتجات
                </button>
              </>
            )}
          </div>
        </div>
      ) : null}
    </>
  );
}
